import{_ as t,o as i,c as n,a2 as e}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Tokoh dan Organisasi Kunci","description":"","frontmatter":{},"headers":[],"relativePath":"id/95-关键人物与组织.md","filePath":"id/95-关键人物与组织.md","lastUpdated":1789183869000}'),s={name:"id/95-关键人物与组织.md"};function r(d,a,u,m,o,k){return i(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="tokoh-dan-organisasi-kunci" tabindex="-1">Tokoh dan Organisasi Kunci <a class="header-anchor" href="#tokoh-dan-organisasi-kunci" aria-label="Permalink to &quot;Tokoh dan Organisasi Kunci&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>95</td></tr><tr><td>Modul</td><td>Lampiran dan Bahan Referensi</td></tr><tr><td>Kata kunci utama</td><td>tokoh kunci, organisasi penting, peran sejarah, fungsi institusi, peradaban simbiosis</td></tr></tbody></table><h2 id="_1-deskripsi" tabindex="-1">1. Deskripsi <a class="header-anchor" href="#_1-deskripsi" aria-label="Permalink to &quot;1. Deskripsi&quot;">​</a></h2><p>Dokumen ini mencakup tokoh kunci dan organisasi penting dalam perjalanan perkembangan Peradaban Simbiosis Jangkar, disusun berdasarkan periode sejarah dan jenis organisasi. Bagian tokoh kunci mencantumkan nama tokoh, periode, kontribusi inti, dan posisi sejarah; bagian organisasi penting mencantumkan nama organisasi, waktu pendirian, fungsi inti, dan peran sejarah. Dokumen ini adalah dokumen pembaruan dinamis; seiring dengan kemajuan sejarah dan evolusi organisasi, akan terus dilengkapi dan direvisi.</p><h2 id="_2-tokoh-kunci" tabindex="-1">2. Tokoh Kunci <a class="header-anchor" href="#_2-tokoh-kunci" aria-label="Permalink to &quot;2. Tokoh Kunci&quot;">​</a></h2><h3 id="_2-1-perintis-pemikiran-di-era-pra-jangkar" tabindex="-1">2.1 Perintis Pemikiran di Era Pra-Jangkar <a class="header-anchor" href="#_2-1-perintis-pemikiran-di-era-pra-jangkar" aria-label="Permalink to &quot;2.1 Perintis Pemikiran di Era Pra-Jangkar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama tokoh</th><th>Periode</th><th>Kontribusi inti</th><th>Posisi sejarah</th></tr></thead><tbody><tr><td>Xuan Hengzi</td><td>Sekitar -500 juta tahun</td><td>Pemikir pertama yang merefleksikan secara sistematis sistem kultivasi gaya penjarahan, mengusulkan prototipe konsep &quot;simbiosis&quot;, penulis volume fragmen &quot;Teori Anti-Penjarahan&quot;</td><td>Perintis kuno pemikiran simbiosis, yang pemikirannya, setelah ratusan juta tahun tidur, menjadi sumber spiritual Peradaban Simbiosis Jangkar</td></tr><tr><td>Wan Lingmu</td><td>Sekitar -100 juta tahun</td><td>Memimpin peradaban eksperimental simbiosis skala besar pertama; meskipun akhirnya dihancurkan oleh peradaban gaya penjarahan, praktiknya membuktikan kelayakan sistem simbiosis</td><td>Perintis praktik simbiosis, dihormati oleh generasi kemudian sebagai &quot;Ibu Simbiosis&quot;</td></tr><tr><td>Mao Juezhe</td><td>Sekitar -10.000 tahun</td><td>Kultivator dari bidang pertama, secara tidak sengaja merasakan simpul stabil dalam jaringan hukum selama kultivasi jangka panjang, menemukan mekanisme jangkar</td><td>Penemu mekanisme jangkar, pembuka Era Kebangkitan Jangkar</td></tr></tbody></table><h3 id="_2-2-pendiri-era-kebangkitan-jangkar" tabindex="-1">2.2 Pendiri Era Kebangkitan Jangkar <a class="header-anchor" href="#_2-2-pendiri-era-kebangkitan-jangkar" aria-label="Permalink to &quot;2.2 Pendiri Era Kebangkitan Jangkar&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama tokoh</th><th>Periode</th><th>Kontribusi inti</th><th>Posisi sejarah</th></tr></thead><tbody><tr><td>Mao Dinggong</td><td>-10000 hingga -9200 tahun</td><td>Murid Mao Juezhe, meneliti secara sistematis mekanisme jangkar, membangun jangkar buatan pertama, penulis &quot;Prinsip Jangkar&quot;</td><td>Pendiri teknologi jangkar, penemu jangkar buatan</td></tr><tr><td>Gong Shengzi</td><td>-6000 hingga -5100 tahun</td><td>Menggabungkan teknologi jangkar dengan pemikiran simbiosis, menciptakan sistem teoretis &quot;Simbiosis Jangkar&quot;, penulis &quot;Teori Simbiosis Jangkar&quot;</td><td>Pencipta teori simbiosis jangkar, mentor spiritual peradaban simbiosis</td></tr><tr><td>Heng Yuangong</td><td>-5000 hingga -4300 tahun</td><td>Membangun kota-negara tipe simbiosis pertama berbasis jangkar, &quot;Kota Heng Yuan&quot;, dan berhasil mempertahankan serangan peradaban gaya penjarahan</td><td>Pendiri kota-negara tipe simbiosis pertama, praktisi sistem simbiosis</td></tr><tr><td>Wan Zushi</td><td>-2000 hingga -1200 tahun</td><td>Memulai &quot;Konferensi Simbiosis Semua Ras&quot; pertama, berkeliling puluhan ras mengadvokasi persatuan simbiosis</td><td>Advokat persatuan semua ras, perintis simbiosis antar-ras</td></tr></tbody></table><h3 id="_2-3-pendiri-negara-di-periode-pembentukan-sistem-simbiosis" tabindex="-1">2.3 Pendiri Negara di Periode Pembentukan Sistem Simbiosis <a class="header-anchor" href="#_2-3-pendiri-negara-di-periode-pembentukan-sistem-simbiosis" aria-label="Permalink to &quot;2.3 Pendiri Negara di Periode Pembentukan Sistem Simbiosis&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama tokoh</th><th>Periode</th><th>Kontribusi inti</th><th>Posisi sejarah</th></tr></thead><tbody><tr><td>Li Xiangong</td><td>-1000 hingga -900 tahun</td><td>Ketua Komite Penyusunan Konstitusi Simbiosis, memimpin penyusunan &quot;Konstitusi Simbiosis&quot;, mempromosikan pengesahan konstitusi melalui referendum rakyat</td><td>Penyusun utama Konstitusi Simbiosis, bapak konstitusional peradaban simbiosis</td></tr><tr><td>Zhi Fagong</td><td>-900 hingga -780 tahun</td><td>Ketua pertama Komite Eksekutif Simbiosis, memimpin pembentukan sistem administratif dan mekanisme penegakan hukum peradaban simbiosis</td><td>Pendiri sistem administratif simbiosis, kepala administratif pertama</td></tr><tr><td>Si Famu</td><td>-900 hingga -800 tahun</td><td>Ketua hakim pertama Pengadilan Simbiosis, membentuk sistem peradilan dan sistem peninjauan inkonstitusional peradaban simbiosis</td><td>Pendiri sistem peradilan simbiosis, kepala peradilan pertama</td></tr><tr><td>San Baishi</td><td>-500 hingga -300 tahun</td><td>Memimpin pekerjaan penggalian dan penyusunan sistem kultivasi asal tiga ratus set, memimpin tim menyelesaikan verifikasi semua tiga ratus set sistem</td><td>Penyusun umum sistem tiga ratus set, komandan umum proyek pembukaan kultivasi</td></tr><tr><td>Bei Zenggong</td><td>-300 hingga -220 tahun</td><td>Memimpin penelitian aplikasi teknologi buah penggandaan, mencapai terobosan rekayasa teknologi amplifikasi deduksi seratus kali lipat</td><td>Ilmuwan utama teknifikasi buah penggandaan, promotor sistem iterasi deduksi</td></tr></tbody></table><h3 id="_2-4-pemimpin-di-periode-pembukaan-dan-aktivasi" tabindex="-1">2.4 Pemimpin di Periode Pembukaan dan Aktivasi <a class="header-anchor" href="#_2-4-pemimpin-di-periode-pembukaan-dan-aktivasi" aria-label="Permalink to &quot;2.4 Pemimpin di Periode Pembukaan dan Aktivasi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama tokoh</th><th>Periode</th><th>Kontribusi inti</th><th>Posisi sejarah</th></tr></thead><tbody><tr><td>Kai Fanggong</td><td>-100 hingga -50 tahun</td><td>Memimpin pekerjaan pembukaan lengkap sistem kultivasi asal tiga ratus set, membentuk sistem alokasi sumber daya kultivasi dan jaringan mentor</td><td>Komandan umum pembukaan sistem tiga ratus set, praktisi &quot;semua orang memiliki jalan&quot;</td></tr><tr><td>Ji Huogong</td><td>-50 tahun hingga tahun nol</td><td>Memimpin implementasi strategi aktivasi 20%, memimpin tim menyelesaikan target aktivasi 20% makhluk dalam 50 tahun</td><td>Komandan umum strategi aktivasi 20%, pembuka era baru peradaban simbiosis</td></tr><tr><td>Sheng Weigong</td><td>Tahun nol hingga 80 tahun</td><td>Memimpin proyek peningkatan dimensi pertama, mempromosikan implementasi jalur peningkatan dimensi empat tahap, mencapai peningkatan dimensi bertahap pertama</td><td>Insinyur utama peningkatan dimensi pertama, pemimpin era peningkatan dimensi</td></tr></tbody></table><h3 id="_2-5-penjelajah-di-era-republik-semua-ras-dan-antar-bidang" tabindex="-1">2.5 Penjelajah di Era Republik Semua Ras dan Antar-Bidang <a class="header-anchor" href="#_2-5-penjelajah-di-era-republik-semua-ras-dan-antar-bidang" aria-label="Permalink to &quot;2.5 Penjelajah di Era Republik Semua Ras dan Antar-Bidang&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama tokoh</th><th>Periode</th><th>Kontribusi inti</th><th>Posisi sejarah</th></tr></thead><tbody><tr><td>Wan Zu Gongzhu</td><td>100 hingga 200 tahun</td><td>Memimpin pekerjaan pendirian Republik Semua Ras, mempromosikan penyusunan katalog semua ras dan kebijakan peleburan antar-ras</td><td>Pendiri Republik Semua Ras, kepala pertama Republik Semua Ras</td></tr><tr><td>Wei Mianmu</td><td>500 hingga 650 tahun</td><td>Direktur pertama Biro Manajemen Bidang, memimpin rencana eksplorasi antar-bidang skala besar, membangun bank umum koordinat bidang</td><td>Perintis eksplorasi antar-bidang, pendiri sistem manajemen bidang</td></tr><tr><td>Kao Gugong</td><td>800 hingga 950 tahun</td><td>Memimpin pematangan akhir rencana arkeologi jarak jauh cermin salinan, mempromosikan arkeologi antar-bidang memasuki era skala</td><td>Ahli utama rencana arkeologi, pendiri arkeologi antar-bidang</td></tr><tr><td>Shi Lügong</td><td>1000 hingga 1150 tahun</td><td>Memimpin terobosan teknologi mundur waktu, mempromosikan pembentukan prinsip &quot;pertama mengamati, kemudian intervensi terbatas&quot;</td><td>Pemimpin teknologi mundur waktu, perumus prinsip hukum waktu</td></tr></tbody></table><h2 id="_3-organisasi-penting" tabindex="-1">3. Organisasi Penting <a class="header-anchor" href="#_3-organisasi-penting" aria-label="Permalink to &quot;3. Organisasi Penting&quot;">​</a></h2><h3 id="_3-1-institusi-kekuatan-tertinggi" tabindex="-1">3.1 Institusi Kekuatan Tertinggi <a class="header-anchor" href="#_3-1-institusi-kekuatan-tertinggi" aria-label="Permalink to &quot;3.1 Institusi Kekuatan Tertinggi&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama organisasi</th><th>Waktu pendirian</th><th>Fungsi inti</th><th>Peran sejarah</th></tr></thead><tbody><tr><td>Dewan Jangkar</td><td>-900 tahun</td><td>Institusi kekuatan tertinggi peradaban simbiosis, terdiri dari perwakilan semua ras secara proporsional, menjalankan kekuasaan legislatif dan kekuasaan pengambilan keputusan atas hal-hal penting</td><td>Institusi pengambilan keputusan tertinggi peradaban simbiosis, perumus semua hukum dan strategi penting</td></tr><tr><td>Komite Eksekutif Simbiosis</td><td>-900 tahun</td><td>Institusi administratif tertinggi peradaban simbiosis, bertanggung jawab atas pelaksanaan konstitusi dan hukum, tata kelola sehari-hari</td><td>Institusi administratif tertinggi peradaban simbiosis, pelaksana hukum dan kebijakan</td></tr><tr><td>Pengadilan Simbiosis</td><td>-900 tahun</td><td>Institusi peradilan tertinggi peradaban simbiosis, menjalankan kekuasaan kehakiman secara independen, bertanggung jawab atas peninjauan inkonstitusional dan persidangan kasus penting</td><td>Institusi peradilan tertinggi peradaban simbiosis, penjaga supremasi hukum</td></tr><tr><td>Komite Pengawasan Jangkar</td><td>-900 tahun</td><td>Institusi pengawasan independen, bertanggung jawab mengawasi semua institusi kekuatan, mencegah penyalahgunaan kekuasaan</td><td>Institusi pengawasan independen peradaban simbiosis, mata rantai kunci dalam keseimbangan kekuatan</td></tr></tbody></table><h3 id="_3-2-institusi-manajemen-khusus" tabindex="-1">3.2 Institusi Manajemen Khusus <a class="header-anchor" href="#_3-2-institusi-manajemen-khusus" aria-label="Permalink to &quot;3.2 Institusi Manajemen Khusus&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama organisasi</th><th>Waktu pendirian</th><th>Fungsi inti</th><th>Peran sejarah</th></tr></thead><tbody><tr><td>Biro Manajemen Bidang</td><td>500 tahun</td><td>Bertanggung jawab atas pemeliharaan bank umum koordinat bidang, persetujuan izin perjalanan, manajemen arkeologi antar-bidang, koordinasi diplomatik antar-bidang</td><td>Institusi utama interaksi antar-bidang, manajer eksplorasi bidang</td></tr><tr><td>Komite Hukum Waktu</td><td>1000 tahun</td><td>Bertanggung jawab atas persetujuan operasi mundur waktu, penelitian hukum waktu, pengawasan pencegahan paradoks waktu</td><td>Institusi persetujuan dan pengawasan operasi mundur waktu, penjaga keamanan hukum waktu</td></tr><tr><td>Komite Audit Hukum Waktu</td><td>1050 tahun</td><td>Bertanggung jawab atas audit pasca operasi mundur waktu, memastikan tidak menyebabkan gangguan garis waktu yang tidak terkendali</td><td>Institusi audit independen operasi waktu, garis pertahanan terakhir keamanan mundur waktu</td></tr><tr><td>Komite Etika Antar-Bidang</td><td>600 tahun</td><td>Merumuskan dan menafsirkan prinsip etika antar-bidang, menyetujui proyek interaksi antar-bidang berisiko tinggi, menerima keluhan pelanggaran etika</td><td>Institusi pengawasan etika interaksi antar-bidang, penjaga subjektivitas peradaban</td></tr><tr><td>Kantor Audit Pengembalian Pengetahuan</td><td>850 tahun</td><td>Bertanggung jawab atas audit operasi pengembalian pengetahuan, memastikan konten yang dikembalikan sesuai dengan prinsip &quot;hanya mengembalikan pengetahuan&quot;</td><td>Institusi audit pengembalian pengetahuan, mata rantai kunci dalam pencegahan polusi antar-bidang</td></tr></tbody></table><h3 id="_3-3-institusi-penelitian-dan-pendidikan" tabindex="-1">3.3 Institusi Penelitian dan Pendidikan <a class="header-anchor" href="#_3-3-institusi-penelitian-dan-pendidikan" aria-label="Permalink to &quot;3.3 Institusi Penelitian dan Pendidikan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama organisasi</th><th>Waktu pendirian</th><th>Fungsi inti</th><th>Peran sejarah</th></tr></thead><tbody><tr><td>Institut Penelitian Jangkar</td><td>-8000 tahun</td><td>Penelitian dasar dan pengembangan aplikasi mekanisme jangkar, pembangunan dan pemeliharaan jangkar buatan</td><td>Institusi penelitian inti teknologi jangkar, salah satu sumber teknologi peradaban simbiosis</td></tr><tr><td>Komite Penyusunan Sistem Tiga Ratus Set</td><td>-500 tahun</td><td>Penggalian, penyusunan, verifikasi, dan optimasi berkelanjutan sistem kultivasi asal tiga ratus set</td><td>Institusi penyusunan dan pemeliharaan sistem tiga ratus set, dukungan teknis untuk pembukaan kultivasi</td></tr><tr><td>Liga Universitas Simbiosis</td><td>-700 tahun</td><td>Organisasi gabungan pendidikan tinggi dan pendidikan kultivasi, bertanggung jawab atas pelatihan bakat lanjutan dan penelitian akademik</td><td>Liga institusi pendidikan tinggi peradaban simbiosis, inti pelatihan bakat dan inovasi akademik</td></tr><tr><td>Fakultas Arkeologi Antar-Bidang</td><td>550 tahun</td><td>Membentuk profesional arkeologi antar-bidang, melakukan penelitian teknologi arkeologi dan inovasi metodologis</td><td>Pusat pelatihan bakat dan penelitian teknologi arkeologi antar-bidang</td></tr><tr><td>Institut Penelitian Hukum Waktu</td><td>950 tahun</td><td>Penelitian teoretis dasar hukum waktu dan penelitian serta pengembangan teknologi mundur waktu</td><td>Institusi inti penelitian hukum waktu, tempat kelahiran teknologi mundur waktu</td></tr></tbody></table><h3 id="_3-4-organisasi-militer-dan-keamanan" tabindex="-1">3.4 Organisasi Militer dan Keamanan <a class="header-anchor" href="#_3-4-organisasi-militer-dan-keamanan" aria-label="Permalink to &quot;3.4 Organisasi Militer dan Keamanan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama organisasi</th><th>Waktu pendirian</th><th>Fungsi inti</th><th>Peran sejarah</th></tr></thead><tbody><tr><td>Tentara Pertahanan Simbiosis</td><td>-850 tahun</td><td>Kekuatan pertahanan reguler peradaban simbiosis, bertanggung jawab atas pertahanan bidang dan penanganan ancaman eksternal</td><td>Kekuatan militer utama peradaban simbiosis, pembela keamanan nasional</td></tr><tr><td>Patroli Bidang</td><td>520 tahun</td><td>Bertanggung jawab atas patroli dan pemantauan keamanan bidang yang telah dieksplorasi, menangani insiden keamanan antar-bidang</td><td>Kekuatan garis depan keamanan antar-bidang, pemelihara ketertiban bidang</td></tr><tr><td>Tim Darurat Polusi Hukum</td><td>600 tahun</td><td>Bertanggung jawab atas respons darurat dan penghapusan polusi dalam insiden polusi hukum dan polusi energi</td><td>Kekuatan respons darurat polusi hukum, penjaga lingkungan kosmik</td></tr><tr><td>Grup Darurat Paradoks Waktu</td><td>1020 tahun</td><td>Bertanggung jawab atas respons darurat dan operasi perbaikan kausal dalam insiden paradoks waktu</td><td>Kekuatan respons darurat paradoks waktu, jaminan terakhir stabilitas garis waktu</td></tr></tbody></table><h3 id="_3-5-organisasi-sipil-dan-sosial" tabindex="-1">3.5 Organisasi Sipil dan Sosial <a class="header-anchor" href="#_3-5-organisasi-sipil-dan-sosial" aria-label="Permalink to &quot;3.5 Organisasi Sipil dan Sosial&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Nama organisasi</th><th>Waktu pendirian</th><th>Fungsi inti</th><th>Peran sejarah</th></tr></thead><tbody><tr><td>Konferensi Simbiosis Semua Ras</td><td>-2000 tahun</td><td>Pertemuan rutin perwakilan semua ras, membahas urusan simbiosis antar-ras, mempromosikan pertukaran budaya</td><td>Platform penting untuk pertukaran semua ras, organisasi perintis Republik Semua Ras</td></tr><tr><td>Asosiasi Kultivator</td><td>-600 tahun</td><td>Organisasi otonomi profesional kultivator, bertanggung jawab atas perlindungan hak kultivator, perumusan norma profesi</td><td>Organisasi otonomi kultivator, promotor normalisasi industri kultivasi</td></tr><tr><td>Asosiasi Konsumen</td><td>-650 tahun</td><td>Organisasi perlindungan hak konsumen, bertanggung jawab atas pembelaan hak konsumen, pendidikan konsumen, pengawasan sosial</td><td>Juru bicara hak konsumen, pengawas sosial ketertiban pasar</td></tr><tr><td>Liga Perlindungan Lingkungan</td><td>-550 tahun</td><td>Organisasi gabungan sipil perlindungan lingkungan, bertanggung jawab atas pengawasan lingkungan, pendidikan lingkungan, kegiatan sukarela restorasi ekologis</td><td>Kekuatan sosial perlindungan lingkungan, promotor peradaban ekologis kosmik</td></tr><tr><td>Asosiasi Persahabatan Antar-Bidang</td><td>580 tahun</td><td>Organisasi sipil yang mempromosikan pertukaran persahabatan antar peradaban antar-bidang, bertanggung jawab atas diplomasi sipil, pertukaran budaya</td><td>Kekuatan inti diplomasi sipil antar-bidang, jembatan pemahaman antar peradaban</td></tr></tbody></table><h2 id="kesimpulan" tabindex="-1">Kesimpulan <a class="header-anchor" href="#kesimpulan" aria-label="Permalink to &quot;Kesimpulan&quot;">​</a></h2><p>Tokoh dan organisasi kunci adalah pembawa hidup sejarah Peradaban Simbiosis Jangkar. Dari perintis pemikiran kuno hingga pemimpin peradaban kontemporer, dari institusi kekuatan tertinggi hingga organisasi sosial sipil, setiap tokoh dan organisasi memainkan peran yang tidak tergantikan dalam narasi besar peradaban simbiosis. Perjuangan dan kontribusi mereka bersama-sama menenun epik megah Peradaban Simbiosis Jangkar, dari ketiadaan menjadi keberadaan, dari kecil menjadi besar, dari bidang sendiri hingga seluruh alam semesta.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>50-Tabel Umum Pembagian Era</li><li>49-Struktur Tata Kelola dan Keseimbangan Kekuatan</li><li>77-Pendirian Republik Semua Ras</li></ul>',30)])])}const h=t(s,[["render",r]]);export{p as __pageData,h as default};
